516	// Proposal 返回当前轮次本地提议；尚未提议时第二个返回值为 false。
517	// 重复调用、登记其他候选均不改变本地提议。
518	func (n *Node) Proposal() (ProposalView, bool) {
519		n.mu.Lock()
520		defer n.mu.Unlock()
521		rs := n.st.currentRoundState()
522		if rs == nil || rs.LocalBlockID == "" {
523			return ProposalView{}, false
524		}
525		return proposalViewOf(rs.Round, rs.Candidates[rs.LocalBlockID]), true
526	}
