127	// 当前轮次，仍必须返回 duplicate-transaction 而不是 tx-expired。历史记录、
128	// 账户待处理列表与已确认序号均不因此变化，拒绝操作不留任何副作用。
129	func TestResubmitExpiredHistoryReturnsDuplicate(t *testing.T) {
