150			t.Fatalf("setup: status = %s, want expired", info.Status)
151		}
152	
153		entriesBefore := len(n.st.Entries)
154	
155		// 原样重建并重投：六字段与签名均与最初被接受时一致，标识因此相同。
156		replay := NewTransaction(keys[0].priv, 1, []byte("expiring-tx"), 1, 2)
157		if replay.ID() != oldID {
158			t.Fatalf("test setup: byte-identical replay id %s != original %s", replay.ID(), oldID)
159		}
160		res, err := n.Submit(replay)
161		if err == nil {
162			t.Fatalf("resubmit of expired history must be rejected, got result %+v", res)
163		}
164		if got := reason(err); got != ReasonDuplicate {
