178		}
179		if blk, ok := n.LatestBlock(); ok {
180			t.Fatalf("rejected resubmit must not confirm a block, got %+v", blk)
181		}
182	
183		// 原记录继续显示 expired，完整交易内容与签名保留，不带区块或替换关联。
184		info, err = n.Tx(oldID)
185		if err != nil {
186			t.Fatal(err)
187		}
188		if info.Status != StatusExpired || info.BlockID != "" || info.BlockHeight != 0 || info.ReplacedBy != "" {
189			t.Fatalf("expired record wrong: %+v", info)
190		}
191		assertTxMatches(t, info.Tx, old)
192	
193		// 账户待处理列表中不能重新出现它，已确认序号也不因此推进。
194		acct := n.Account(keys[0].pub)
195		if acct.ConfirmedSequence != 0 || len(acct.Pending) != 0 {
196			t.Fatalf("expired tx must not reappear pending nor advance sequence: %+v", acct)
197		}
198	}
199	
200	// 对照：一笔从未被接受、提交时就已经到期的交易返回 tx-expired，
201	// 并且查询不到任何历史记录。它与上面的历史旧交易可以同发送者同序号，
202	// 区别仅在交易标识（内容与签名不同）。
203	func TestNeverAcceptedExpiredTxRejectedWithoutHistory(t *testing.T) {
204		keys := genKeys(t, 4)
205		n, _ := newTestNode(t, keys, 10)
206	
207		// 先制造一条 expired 历史，保证“历史交易”与“从未接受交易”同场可比。
208		hist := NewTransaction(keys[0].priv, 1, []byte("accepted-then-expired"), 1, 2)
209		if _, err := n.Submit(hist); err != nil {
210			t.Fatal(err)
211		}
212		if _, err := n.EndRound(); err != nil {
213			t.Fatal(err)
214		}
215		if info, _ := n.Tx(hist.ID()); info.Status != StatusExpired {
216			t.Fatalf("setup: history status = %s, want expired", info.Status)
217		}
218		entriesBefore := len(n.st.Entries)
219	
220		// 同发送者同序号、但内容与签名全新的另一笔交易：当前为第 2 轮，提交即到期。
221		fresh := NewTransaction(keys[0].priv, 1, []byte("never-accepted"), 1, 2)
222		if fresh.ID() == hist.ID() {
223			t.Fatal("test setup: fresh tx must have a distinct id from history tx")
224		}
225		res, err := n.Submit(fresh)
226		if err == nil {
227			t.Fatalf("already-expired new tx must be rejected, got result %+v", res)
228		}
229		if got := reason(err); got != ReasonExpired {
230			t.Fatalf("never-accepted expired tx reason = %q, want %s", got, ReasonExpired)
231		}
232		if res != nil {
233			t.Fatalf("rejected submit must return nil result, got %+v", res)
234		}
235	
236		// 从未被接受：按标识查询不到历史，条目数不增加。
237		if _, err := n.Tx(fresh.ID()); reason(err) != ReasonUnknownTx {
238			t.Fatalf("fresh expired tx lookup reason = %v, want %s", err, ReasonUnknownTx)
239		}
240		if len(n.st.Entries) != entriesBefore {
241			t.Fatalf("entries changed %d -> %d; expired rejection keeps no history",
242				entriesBefore, len(n.st.Entries))
243		}
244	
245		// 既有 expired 历史不受这次拒绝影响。
246		histInfo, err := n.Tx(hist.ID())
247		if err != nil {
248			t.Fatal(err)
249		}
250		if histInfo.Status != StatusExpired {
251			t.Fatalf("history record changed: status = %s, want expired", histInfo.Status)
252		}
253	
254		// 同场再验一次分野：历史交易原样重投是 duplicate，而非 tx-expired。
255		replay := NewTransaction(keys[0].priv, 1, []byte("accepted-then-expired"), 1, 2)
256		if replay.ID() != hist.ID() {
257			t.Fatalf("test setup: replay id %s != history id %s", replay.ID(), hist.ID())
258		}
259		if _, err := n.Submit(replay); reason(err) != ReasonDuplicate {
260			t.Fatalf("history replay reason = %v, want %s", err, ReasonDuplicate)
261		}
262	}
263	
264	// 过期只结束旧交易的有效性，并不占用该账户尚未确认的序号。同发送者同序号
265	// 重新签署一笔到期轮次晚于当前轮次的新交易，只要符合既有接收条件就正常入队；
266	// 它不是替换（即使新费用更低也不能按 fee-not-higher 拒绝），旧记录保持 expired。
267	func TestExpiryFreesSequenceForFreshlySignedTx(t *testing.T) {
268		keys := genKeys(t, 4)
269		n, _ := newTestNode(t, keys, 10)
270	
271		old := NewTransaction(keys[0].priv, 1, []byte("old-expired"), 2, 2)
272		if _, err := n.Submit(old); err != nil {
273			t.Fatal(err)
274		}
275		oldID := old.ID()
276		if _, err := n.EndRound(); err != nil {
277			t.Fatal(err)
278		}
279		if info, _ := n.Tx(oldID); info.Status != StatusExpired {
280			t.Fatalf("setup: status = %s, want expired", info.Status)
281		}
282		entriesBefore := len(n.st.Entries)
283	
284		// 同发送者同序号重新签署：新内容、费用甚至低于旧交易、到期轮次晚于当前轮次。
285		renewed := NewTransaction(keys[0].priv, 1, []byte("renewed"), 1, 10)
286		if renewed.ID() == oldID {
287			t.Fatal("test setup: renewed tx must have a distinct id")
288		}
289		if n.CurrentRound() >= renewed.Expiry {
290			t.Fatalf("test setup: renewed expiry %d must be greater than current round %d",
291				renewed.Expiry, n.CurrentRound())
292		}
293		res, err := n.Submit(renewed)
294		if err != nil {
295			t.Fatalf("freshly signed tx for expired sequence must be accepted: %v", err)
296		}
297		newID := renewed.ID()
298		// 旧交易早已退出池：这是一次全新接收，不是替换，也没有挤出任何交易。
299		if res.TxID != newID || res.ReplacedID != "" || res.EvictedID != "" {
300			t.Fatalf("renewed submit result wrong: %+v", res)
301		}
302	
303		// 仅新增新交易一条记录；旧记录仍为 expired，替换关联保持为空。
304		if len(n.st.Entries) != entriesBefore+1 {
305			t.Fatalf("entries changed %d -> %d, want %d", entriesBefore, len(n.st.Entries), entriesBefore+1)
306		}
307		oldInfo, err := n.Tx(oldID)
308		if err != nil {
309			t.Fatal(err)
310		}
311		if oldInfo.Status != StatusExpired || oldInfo.ReplacedBy != "" {
312			t.Fatalf("old record changed: status=%s replacedBy=%q, want expired/empty",
313				oldInfo.Status, oldInfo.ReplacedBy)
314		}
315		// 新交易按自己的标识可查，内容与签名完整，处于排队状态。
316		newInfo, err := n.Tx(newID)
317		if err != nil {
318			t.Fatal(err)
319		}
320		if newInfo.Status != StatusQueued {
321			t.Fatalf("renewed tx status = %s, want queued", newInfo.Status)
322		}
323		assertTxMatches(t, newInfo.Tx, renewed)
324	
325		// 账户待处理列表中，序号 1 对应的是有效的新交易；旧 expired 交易不出现。
326		acct := n.Account(keys[0].pub)
327		if acct.ConfirmedSequence != 0 || acct.Gap != 0 || len(acct.Pending) != 1 {
328			t.Fatalf("account wrong after renewal: %+v", acct)
329		}
330		p := acct.Pending[0]
331		if p.ID != newID || p.Status != StatusQueued || p.Note != "waiting-pack" {
332			t.Fatalf("pending entry wrong: %+v", p)
333		}
334	
335		// 正常进入排队即可被下一轮打包，证明它走的是既有接收规则。
336		prop, err := n.Propose()
337		if err != nil {
338			t.Fatal(err)
339		}
340		if prop.Round != 2 || len(prop.TxIDs) != 1 || prop.TxIDs[0] != newID {
341			t.Fatalf("renewed tx should pack in round 2, got %+v", prop)
342		}
343	}
344

